# (course, phrase suffix) -> (action, new_known, new_target, family, reason)
E_='ita_for_eng'; J='ita_for_jpn'
P={}
def rw(c,pid,k,t,fam,why): P[(c,pid)]=('RE-WORD',k,t,fam,why)
def dl(c,pid,fam,why): P[(c,pid)]=('DELETE','','',fam,why)
F1='1 LEGO swapped for a different verb'; F2='2 LEGO grew to take in the next words'; F3='3 Formal sir/madam LEGO is now the whole sentence'
F4='4 Bound or contracted form breaks the LEGO'; F5='5 A word sits inside the LEGO'; F6='6 Component row (not a practice phrase)'
